  "ch7.size.mountain": "一座山",
  "ch7.size.building": "一栋楼",
  "ch7.size.person": "一个人",
  "ch7.size.hand": "一只手",
  "ch7.size.fingernail": "一片指甲",
  "ch7.size.grain": "一粒沙",
  "ch7.size.hair": "一根头发的粗细",
  "ch7.size.cell": "一个细胞",
  "ch7.size.virus": "一个病毒",
